def run_analysis(args):
    try:
        project_manager = ProjectManager()
        project_data = project_manager.get_project_data(
            args.project, debug_mode=args.debug
        )
        correction_matrix, lower_hsv, upper_hsv, center_hsv, dataset_debug_info = (
            project_data["correction_matrix"],
            project_data["lower_hsv"],
            project_data["upper_hsv"],
            project_data["center_hsv"],
            project_data["dataset_debug_info"],
        )
        print(
            f"Loaded project '{args.project}' with HSV range: {lower_hsv} - {upper_hsv}"
        )

        color_corrector = ColorCorrector()
        color_analyzer = ColorAnalyzer()

        if args.image:
            if os.path.isdir(args.image):
                for filename in os.listdir(args.image):
                    if filename.lower().endswith((".png", ".jpg", ".jpeg")):
                        image_path = os.path.join(args.image, filename)
                        process_image(
                            image_path,
                            args,
                            project_manager,
                            color_corrector,
                            color_analyzer,
                            lower_hsv,
                            upper_hsv,
                            center_hsv,
                            correction_matrix,
                            dataset_debug_info,
                        )
            else:
                process_image(
                    args.image,
                    args,
                    project_manager,
                    color_corrector,
                    color_analyzer,
                    lower_hsv,
                    upper_hsv,
                    center_hsv,
                    correction_matrix,
                    dataset_debug_info,
                )

        if args.video:
            if os.path.isdir(args.video):
                for filename in os.listdir(args.video):
                    if filename.lower().endswith((".mp4", ".avi", ".mov")):
                        video_path = os.path.join(args.video, filename)
                        process_video(
                            video_path,
                            args,
                            color_corrector,
                            color_analyzer,
                            None,
                            lower_hsv,
                            upper_hsv,
                            center_hsv,
                            correction_matrix,
                            dataset_debug_info,
                        )
            else:
                process_video(
                    args.video,
                    args,
                    color_corrector,
                    color_analyzer,
                    None,
                    lower_hsv,
                    upper_hsv,
                    center_hsv,
                    correction_matrix,
                    dataset_debug_info,
                )

    except (ValueError, FileNotFoundError) as e:
        print(f"Error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")


def process_image(
    image_path,
    args,
    project_manager,
    color_corrector,
    color_analyzer,
    lower_hsv,
    upper_hsv,
    center_hsv,
    correction_matrix,
